SELECT run_id, gpu_hours FROM llm_run_summary WHERE run_id = 'planner:week_fc_p90';
SELECT run_id, gpu_hours, CAST(metrics->>'decode_gpus_per_worker' AS float) as dgpu FROM llm_run_summary WHERE run_id IN (SELECT run_id FROM v_dim WHERE is_current = true AND policy = 'static' AND kind = 'K2');
SELECT * FROM v_cost_ratio WHERE is_current = true AND experiment = 'planner';
